/**
 * A mini template engine: interpolation with HTML escaping, dotted paths,
 * sections and inverted sections over a context stack, and partials.
 */

/** Error raised for malformed templates and impossible renders. */
export class TemplateError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   * @param {number} index Zero-based offset of the offending tag.
   */
  constructor(code, message, index) {
    super(message);
    this.name = 'TemplateError';
    this.code = code;
    this.index = index;
  }
}

const ESCAPES = [
  ['&', '&amp;'],
  ['<', '&lt;'],
  ['>', '&gt;'],
  ['"', '&quot;'],
  ["'", '&#39;'],
];

const NAME_PATTERN = /^(\.|[A-Za-z0-9_$]+(\.[A-Za-z0-9_$]+)*)$/;
const DEFAULT_MAX_DEPTH = 16;

/**
 * Escape the five characters that are unsafe in HTML text and attributes.
 *
 * @param {string} text Text to escape.
 * @returns {string} Escaped text.
 */
export function escapeHtml(text) {
  if (typeof text !== 'string') throw new TemplateError('BAD_INPUT', 'text must be a string', 0);
  let result = text;
  for (const [from, to] of ESCAPES) result = result.split(from).join(to);
  return result;
}

/**
 * Classify the sigil at the front of a tag.
 *
 * @param {string} body Raw tag body without the braces.
 * @returns {{sigil: string, name: string}} Sigil (empty for a plain variable) and trimmed name.
 */
function splitTag(body) {
  const trimmed = body.trim();
  if (trimmed === '') return { sigil: '', name: '' };
  if ('#^/>&!'.includes(trimmed[0])) {
    return { sigil: trimmed[0], name: trimmed.slice(1).trim() };
  }
  return { sigil: '', name: trimmed };
}

/**
 * Parse a template into nodes.
 *
 * @param {string} template Template source.
 * @returns {object[]} Node list.
 */
export function parse(template) {
  if (typeof template !== 'string') throw new TemplateError('BAD_TEMPLATE', 'template must be a string', 0);
  const root = [];
  const open = [{ name: null, children: root, index: 0 }];
  const current = () => open[open.length - 1];
  let index = 0;
  let text = '';

  const flushText = () => {
    if (text === '') return;
    current().children.push({ type: 'text', value: text });
    text = '';
  };

  while (index < template.length) {
    const start = template.indexOf('{{', index);
    if (start === -1) {
      text += template.slice(index);
      index = template.length;
      break;
    }
    text += template.slice(index, start);
    const triple = template.startsWith('{{{', start);
    const opener = triple ? 3 : 2;
    const closer = triple ? '}}}' : '}}';
    const stop = template.indexOf(closer, start + opener);
    if (stop === -1) throw new TemplateError('UNCLOSED_TAG', 'unclosed tag', start);
    const { sigil, name } = splitTag(template.slice(start + opener, stop));
    index = stop + closer.length;

    if (sigil === '!') continue;
    if (name === '') throw new TemplateError('EMPTY_NAME', 'a tag needs a name', start);
    if (!NAME_PATTERN.test(name)) throw new TemplateError('BAD_NAME', `invalid name: ${name}`, start);

    if (sigil === '#' || sigil === '^') {
      flushText();
      const section = { type: 'section', name, inverted: sigil === '^', children: [] };
      current().children.push(section);
      open.push({ name, children: section.children, index: start });
      continue;
    }
    if (sigil === '/') {
      if (open.length === 1 || current().name !== name) {
        throw new TemplateError('MISMATCHED_SECTION', `unexpected closing tag: ${name}`, start);
      }
      flushText();
      open.pop();
      continue;
    }
    flushText();
    if (sigil === '>') current().children.push({ type: 'partial', name });
    else current().children.push({ type: 'variable', name, escaped: !triple && sigil !== '&' });
  }

  if (open.length > 1) {
    throw new TemplateError('UNCLOSED_SECTION', `unclosed section: ${current().name}`, current().index);
  }
  flushText();
  return root;
}

/**
 * Report whether a value makes a section render nothing.
 *
 * @param {unknown} value Resolved section value.
 * @returns {boolean} True when the section is empty.
 */
function isEmpty(value) {
  if (Array.isArray(value)) return value.length === 0;
  return !value;
}

/**
 * Render a resolved value as text.
 *
 * @param {unknown} value Resolved value.
 * @returns {string} Text, empty for null and undefined.
 */
function stringify(value) {
  if (value === null || value === undefined) return '';
  return String(value);
}

/**
 * Report whether a frame carries a property.
 *
 * @param {unknown} frame Context frame.
 * @param {string} key Property name.
 * @returns {boolean} True when the frame owns the property.
 */
function owns(frame, key) {
  return frame !== null && typeof frame === 'object' && Object.prototype.hasOwnProperty.call(frame, key);
}

/**
 * Resolve a name against the context stack, innermost frame first.
 *
 * @param {unknown[]} stack Context frames, innermost first.
 * @param {string} path Dotted path or `.` for the current context.
 * @returns {unknown} The resolved value, or undefined.
 */
function resolve(stack, path) {
  if (path === '.') return stack[0];
  const parts = path.split('.');
  for (const frame of stack) {
    if (!owns(frame, parts[0])) continue;
    let value = frame[parts[0]];
    for (const part of parts.slice(1)) {
      if (!owns(value, part)) return undefined;
      value = value[part];
    }
    return value;
  }
  return undefined;
}

/**
 * Render a node list against a context stack.
 *
 * @param {object[]} nodes Nodes to render.
 * @param {unknown[]} stack Context frames, innermost first.
 * @param {{partials: Record<string, string>, maxDepth: number, depth: number}} state Shared render state.
 * @returns {string} Rendered text.
 */
function renderNodes(nodes, stack, state) {
  let output = '';
  for (const node of nodes) {
    if (node.type === 'text') {
      output += node.value;
      continue;
    }
    if (node.type === 'variable') {
      const text = stringify(resolve(stack, node.name));
      output += node.escaped ? escapeHtml(text) : text;
      continue;
    }
    if (node.type === 'section') {
      const value = resolve(stack, node.name);
      if (node.inverted) {
        if (isEmpty(value)) output += renderNodes(node.children, stack, state);
        continue;
      }
      if (isEmpty(value)) continue;
      if (Array.isArray(value)) {
        for (const item of value) output += renderNodes(node.children, [item, ...stack], state);
      } else if (typeof value === 'object') {
        output += renderNodes(node.children, [value, ...stack], state);
      } else {
        output += renderNodes(node.children, stack, state);
      }
      continue;
    }
    const source = state.partials[node.name];
    if (typeof source !== 'string') {
      throw new TemplateError('UNKNOWN_PARTIAL', `unknown partial: ${node.name}`, 0);
    }
    if (state.depth >= state.maxDepth) {
      throw new TemplateError('PARTIAL_DEPTH', `partials nested deeper than ${state.maxDepth}`, 0);
    }
    state.depth += 1;
    output += renderNodes(parse(source), stack, state);
    state.depth -= 1;
  }
  return output;
}

/**
 * Render a template.
 *
 * @param {string} template Template source.
 * @param {unknown} [data] Root context.
 * @param {{partials?: Record<string, string>, maxDepth?: number}} [options] Partials and recursion limit.
 * @returns {string} Rendered text.
 */
export function render(template, data = {}, options = {}) {
  if (typeof options !== 'object' || options === null) {
    throw new TemplateError('BAD_INPUT', 'options must be an object', 0);
  }
  const partials = options.partials ?? {};
  if (typeof partials !== 'object' || partials === null) {
    throw new TemplateError('BAD_INPUT', 'partials must be an object', 0);
  }
  const maxDepth = options.maxDepth ?? DEFAULT_MAX_DEPTH;
  if (!Number.isInteger(maxDepth) || maxDepth < 1) {
    throw new TemplateError('BAD_INPUT', 'maxDepth must be a positive integer', 0);
  }
  return renderNodes(parse(template), [data], { partials, maxDepth, depth: 0 });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { TemplateError, escapeHtml, parse, render } from '../src/index.js';

/** Deterministic 32-bit PRNG so generated values replay identically. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Undo escaping, innermost entity last, so double escaping is visible. */
function unescapeHtml(text) {
  return text
    .split('&#39;')
    .join("'")
    .split('&quot;')
    .join('"')
    .split('&gt;')
    .join('>')
    .split('&lt;')
    .join('<')
    .split('&amp;')
    .join('&');
}

test('escapeHtml escapes the ampersand before it escapes anything else', () => {
  assert.equal(escapeHtml('a & b'), 'a &amp; b');
  assert.equal(escapeHtml('&<>'), '&amp;&lt;&gt;');
  assert.equal(escapeHtml('<a href="x">'), '&lt;a href=&quot;x&quot;&gt;');
  assert.equal(escapeHtml("it's"), 'it&#39;s');
  assert.equal(escapeHtml('&amp;'), '&amp;amp;');
  assert.equal(escapeHtml('1 < 2 && 3 > 2'), '1 &lt; 2 &amp;&amp; 3 &gt; 2');
  assert.equal(escapeHtml(''), '');
  assert.equal(escapeHtml('plain text'), 'plain text');
  assert.throws(() => escapeHtml(5), { name: 'TemplateError', code: 'BAD_INPUT' });
});

test('parse builds the node list', () => {
  assert.deepEqual(parse('hello'), [{ type: 'text', value: 'hello' }]);
  assert.deepEqual(parse(''), []);
  assert.deepEqual(parse('{{name}}'), [{ type: 'variable', name: 'name', escaped: true }]);
  assert.deepEqual(parse('{{{name}}}'), [{ type: 'variable', name: 'name', escaped: false }]);
  assert.deepEqual(parse('{{& name }}'), [{ type: 'variable', name: 'name', escaped: false }]);
  assert.deepEqual(parse('{{ a.b }}'), [{ type: 'variable', name: 'a.b', escaped: true }]);
  assert.deepEqual(parse('{{.}}'), [{ type: 'variable', name: '.', escaped: true }]);
  assert.deepEqual(parse('a{{! note }}b'), [{ type: 'text', value: 'ab' }]);
  assert.deepEqual(parse('{{>bit}}'), [{ type: 'partial', name: 'bit' }]);
  assert.deepEqual(parse('{{#a}}x{{/a}}'), [
    { type: 'section', name: 'a', inverted: false, children: [{ type: 'text', value: 'x' }] },
  ]);
  assert.deepEqual(parse('{{^a}}x{{/a}}'), [
    { type: 'section', name: 'a', inverted: true, children: [{ type: 'text', value: 'x' }] },
  ]);
});

test('interpolation escapes by default and stringifies every value', () => {
  assert.equal(render('{{a}}', { a: '<b>' }), '&lt;b&gt;');
  assert.equal(render('{{{a}}}', { a: '<b>' }), '<b>');
  assert.equal(render('{{&a}}', { a: '<b>' }), '<b>');
  assert.equal(render('{{a}}', {}), '');
  assert.equal(render('{{a}}', { a: null }), '');
  assert.equal(render('{{a}}', { a: undefined }), '');
  assert.equal(render('{{a}}', { a: 0 }), '0', 'zero is a value, not an absence');
  assert.equal(render('{{a}}', { a: false }), 'false', 'false is a value, not an absence');
  assert.equal(render('{{a}}', { a: '' }), '');
  assert.equal(render('{{a}}', { a: 12.5 }), '12.5');
  assert.equal(render('x{{a}}y', { a: '-' }), 'x-y');
  assert.equal(render('{{a.b.c}}', { a: { b: { c: 'deep' } } }), 'deep');
  assert.equal(render('{{a.b}}', { a: {} }), '');
  assert.equal(render('{{a.b}}', { a: 'text' }), '');
});

test('sections iterate, scope and skip', () => {
  assert.equal(render('{{#xs}}[{{.}}]{{/xs}}', { xs: [1, 2, 3] }), '[1][2][3]');
  assert.equal(render('{{#xs}}{{n}}{{/xs}}', { xs: [{ n: 1 }, { n: 2 }] }), '12');
  assert.equal(render('{{#o}}{{n}}{{/o}}', { o: { n: 'x' } }), 'x');
  assert.equal(render('{{#t}}yes{{/t}}', { t: true }), 'yes');
  assert.equal(render('{{#t}}{{t}}{{/t}}', { t: 'v' }), 'v');
  assert.equal(render('{{#xs}}x{{/xs}}', { xs: [] }), '');
  assert.equal(render('{{#xs}}x{{/xs}}', { xs: 0 }), '');
  assert.equal(render('{{#xs}}x{{/xs}}', {}), '');
  assert.equal(render('{{#a}}{{#b}}{{.}}{{/b}}{{/a}}', { a: { b: ['q'] } }), 'q');
});

test('inverted sections render exactly when a section would not', () => {
  const cases = [
    [[], 'none'],
    [[1], ''],
    [false, 'none'],
    [true, ''],
    [0, 'none'],
    ['', 'none'],
    [undefined, 'none'],
    [null, 'none'],
    ['x', ''],
    [{}, ''],
  ];
  for (const [value, expected] of cases) {
    assert.equal(render('{{^a}}none{{/a}}', { a: value }), expected, `inverted for ${JSON.stringify(value)}`);
  }
  assert.equal(render('{{^missing}}none{{/missing}}', {}), 'none');
});

test('the context stack is searched innermost first', () => {
  assert.equal(render('{{#xs}}{{name}}{{/xs}}', { name: 'outer', xs: [{ name: 'inner' }, {}] }), 'innerouter');
  assert.equal(render('{{#xs}}{{top}}{{/xs}}', { top: 'T', xs: [{}, {}] }), 'TT');
  assert.equal(render('{{#a}}{{b.c}}{{/a}}', { a: [{}], b: { c: 'parent' } }), 'parent');
  assert.equal(render('{{#a}}{{#b}}{{v}}{{/b}}{{/a}}', { v: 'root', a: { v: 'mid', b: { x: 1 } } }), 'mid');
  assert.equal(render('{{#a}}{{v}}{{/a}}{{v}}', { v: 'root', a: [{ v: 'own' }] }), 'ownroot');
});

test('partials render in the current context', () => {
  assert.equal(render('{{>p}}', { x: 'v' }, { partials: { p: '[{{x}}]' } }), '[v]');
  assert.equal(render('{{>p}}', {}, { partials: { p: '{{>q}}', q: 'deep' } }), 'deep');
  assert.equal(render('{{#xs}}{{>p}}{{/xs}}', { xs: [{ n: 1 }, { n: 2 }] }, { partials: { p: '{{n}}' } }), '12');
  assert.equal(
    render('{{>p}}{{>p}}{{>p}}{{>p}}{{>p}}', {}, { partials: { p: 'p' }, maxDepth: 3 }),
    'ppppp',
    'partials side by side do not nest',
  );
  assert.equal(render('{{>p}}', {}, { partials: { p: '{{>q}}{{>q}}', q: 'x' }, maxDepth: 2 }), 'xx');
  assert.throws(() => render('{{>self}}', {}, { partials: { self: 'x{{>self}}' } }), {
    code: 'PARTIAL_DEPTH',
  });
  assert.throws(() => render('{{>p}}', {}, { partials: { p: '{{>q}}', q: '{{>r}}', r: 'x' }, maxDepth: 2 }), {
    code: 'PARTIAL_DEPTH',
  });
  assert.throws(() => render('{{>missing}}', {}), { code: 'UNKNOWN_PARTIAL', message: 'unknown partial: missing' });
});

test('malformed templates report a code and an offset', () => {
  const cases = [
    ['{{a', 'UNCLOSED_TAG', 0],
    ['x {{a', 'UNCLOSED_TAG', 2],
    ['{{{a}}', 'UNCLOSED_TAG', 0],
    ['{{#a}}x', 'UNCLOSED_SECTION', 0],
    ['a{{#b}}', 'UNCLOSED_SECTION', 1],
    ['{{#a}}x{{/b}}', 'MISMATCHED_SECTION', 7],
    ['{{/a}}', 'MISMATCHED_SECTION', 0],
    ['{{}}', 'EMPTY_NAME', 0],
    ['{{#}}', 'EMPTY_NAME', 0],
    ['{{ }}', 'EMPTY_NAME', 0],
    ['{{a b}}', 'BAD_NAME', 0],
    ['{{a..b}}', 'BAD_NAME', 0],
  ];
  for (const [template, code, index] of cases) {
    assert.throws(() => render(template, {}), { name: 'TemplateError', code, index }, `case ${template}`);
  }
  assert.throws(() => render(5, {}), { code: 'BAD_TEMPLATE' });
  assert.throws(() => render('{{a}}', {}, null), { code: 'BAD_INPUT' });
  assert.throws(() => render('{{a}}', {}, { maxDepth: 0 }), { code: 'BAD_INPUT' });
  assert.throws(() => render('{{a}}', {}, { partials: 'x' }), { code: 'BAD_INPUT' });
});

test('a whole page renders end to end', () => {
  const template =
    '<ul>{{#items}}<li>{{name}}: {{{html}}} ({{count}})</li>{{/items}}{{^items}}<li>empty</li>{{/items}}</ul>';
  assert.equal(
    render(template, {
      items: [
        { name: 'a<b', html: '<i>x</i>', count: 0 },
        { name: "o'k", html: '&', count: 2 },
      ],
    }),
    '<ul><li>a&lt;b: <i>x</i> (0)</li><li>o&#39;k: & (2)</li></ul>',
  );
  assert.equal(render(template, { items: [] }), '<ul><li>empty</li></ul>');
  assert.equal(render(template, {}), '<ul><li>empty</li></ul>');
});

test('escaping round-trips for generated values', () => {
  const pick = mulberry32(707070);
  const alphabet = ['a', '<', '>', '&', '"', "'", ' ', ';', '#', '日', '\n', 'amp'];
  for (let round = 0; round < 300; round += 1) {
    const length = Math.floor(pick() * 8);
    let value = '';
    for (let index = 0; index < length; index += 1) value += alphabet[Math.floor(pick() * alphabet.length)];
    const escaped = render('{{v}}', { v: value });
    assert.equal(unescapeHtml(escaped), value, `round ${round} for ${JSON.stringify(value)}`);
    assert.equal(render('{{{v}}}', { v: value }), value, 'a raw tag never rewrites its value');
    assert.equal(escaped, escapeHtml(value), 'interpolation escapes exactly like escapeHtml');
    assert.equal(escaped.includes('<'), false, 'escaped output has no raw angle bracket');
  }
});

test('a section and its inverse never both render', () => {
  const pick = mulberry32(808080);
  const values = [[], [1], [1, 2], false, true, 0, 1, '', 'x', null, undefined, {}, { a: 1 }];
  for (let round = 0; round < 200; round += 1) {
    const value = values[Math.floor(pick() * values.length)];
    const output = render('{{#a}}X{{/a}}{{^a}}Y{{/a}}', { a: value });
    const positive = output.includes('X');
    const negative = output.includes('Y');
    assert.notEqual(positive, negative, `exactly one branch renders for ${JSON.stringify(value)}`);
    if (Array.isArray(value)) {
      assert.equal(output, value.length === 0 ? 'Y' : 'X'.repeat(value.length), 'arrays repeat their body');
    }
  }
});

