const defects = {
  comparatorOrder: [
    `  if (left.priority !== right.priority) return right.priority - left.priority;
  if (left.deadlineMs !== right.deadlineMs) return left.deadlineMs < right.deadlineMs ? -1 : 1;`,
    `  if (left.deadlineMs !== right.deadlineMs) return left.deadlineMs < right.deadlineMs ? -1 : 1;
  if (left.priority !== right.priority) return right.priority - left.priority;`,
  ],
  deadlineBoundary: [
    '      if (now > job.deadlineMs) {',
    '      if (now >= job.deadlineMs) {',
  ],
  cascadeDepth: [
    `        job.status = 'blocked';
        this.#log('block', job.id);
        queue.push(job.id);`,
    `        job.status = 'blocked';
        this.#log('block', job.id);`,
  ],
  dependencyDone: [
    "    return job.deps.every((dep) => this.#jobs.get(dep).status === 'done');",
    "    return job.deps.every((dep) => this.#jobs.get(dep).status !== 'pending');",
  ],
  cancelTerminal: [
    `    const job = this.#require(id);
    if (job.status !== 'pending') return false;`,
    `    const job = this.#require(id);
    if (job.status === 'running') return false;`,
  ],
};

const [source, destination, ...wanted] = process.argv.slice(2);
let text = readFileSync(source, 'utf8');
const names = wanted.length === 0 ? Object.keys(defects) : wanted;
for (const name of names) {
  const [from, to] = defects[name];
  if (!text.includes(from)) throw new Error(`defect site not found: ${name}`);
  text = text.replace(from, to);
}
writeFileSync(destination, text);
process.stdout.write(`planted: ${names.join(', ')}\n`);

