for (const file of process.argv.slice(2)) {
  let text = readFileSync(file, 'utf8');
  if (!text.includes(from)) throw new Error(`render body not found in ${file}`);
  if (!text.includes(anchor)) throw new Error(`doc anchor not found in ${file}`);
  text = text.replace(from, to).replace(anchor, insert);
  writeFileSync(file, text);
  process.stdout.write(`updated ${file}\n`);
}

